LANGUAGE plpgsql AS $$
BEGIN
    UPDATE club SET Club_name = 'phase_9';
    UPDATE player SET Occupation = 'log_phase_9';
    DELETE FROM club WHERE Club_ID < para_Club_ID + 8;
    DELETE FROM player WHERE Votes < para_Votes;
    UPDATE club SET Region = para_Club_name WHERE Start_year < para_Start_year;
    UPDATE player SET Sponsor_name = para_Occupation WHERE Player_ID = para_Player_ID;
